package com.bowlsofmayo;

import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.util.ArrayList;
import java.util.Base64;
import java.util.Collections;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;
import javax.imageio.ImageIO;
import net.runelite.api.Item;
import net.runelite.api.ItemComposition;
import net.runelite.api.ItemContainer;
import net.runelite.client.game.ItemManager;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

final class BankSnapshots
{
    private static final Logger LOG = LoggerFactory.getLogger(BankSnapshots.class);
    private final Map<Integer, String> itemIcons = new ConcurrentHashMap<>();
    private final Set<Integer> pendingIcons = new HashSet<>();

    String icon(int id)
    {
        return itemIcons.get(id);
    }

    List<TrackerData.BankItem> readItems(ItemManager itemManager, ItemContainer container)
    {
        List<TrackerData.BankItem> result = new ArrayList<>();
        for (Item item : container.getItems())
        {
            if (item.getId() > 0 && item.getQuantity() > 0)
            {
                TrackerData.BankItem entry = new TrackerData.BankItem();
                entry.id = item.getId();
                entry.qty = item.getQuantity();
                entry.name = itemManager.getItemComposition(item.getId()).getName();
                int baseId = itemManager.canonicalize(item.getId());
                ItemComposition definition = itemManager.getItemComposition(baseId);
                entry.price = itemManager.getItemPrice(baseId);
                entry.highAlch = definition.getHaPrice();
                result.add(entry);
            }
        }
        return Collections.unmodifiableList(result);
    }

    static List<TrackerData.BankItem> combinedItems(List<TrackerData.BankItem> personal,
        List<TrackerData.BankItem> shared)
    {
        List<TrackerData.BankItem> items = new ArrayList<>();
        if (personal != null)
        {
            items.addAll(personal);
        }
        if (shared != null)
        {
            items.addAll(shared);
        }
        return items;
    }

    void prepareIcons(ItemManager itemManager, List<TrackerData.BankItem> bank, List<TrackerData.BankItem> groupStorage)
    {
        int scheduled = 0;
        for (TrackerData.BankItem item : combinedItems(bank, groupStorage))
        {
            if (itemIcons.containsKey(item.id) || !pendingIcons.add(item.id))
            {
                continue;
            }
            net.runelite.client.util.AsyncBufferedImage image = itemManager.getImage(item.id);
            if (image == null)
            {
                pendingIcons.remove(item.id);
                LOG.warn("Cannot render bank item icon {}", item.id);
                continue;
            }
            image.onLoaded(() -> {
                try
                {
                    ByteArrayOutputStream bytes = new ByteArrayOutputStream();
                    if (!ImageIO.write(image, "png", bytes))
                    {
                        throw new IOException("PNG encoder unavailable");
                    }
                    itemIcons.put(item.id, Base64.getEncoder().encodeToString(bytes.toByteArray()));
                }
                catch (IOException error)
                {
                    LOG.warn("Failed to encode bank item icon {}", item.id, error);
                }
                finally
                {
                    pendingIcons.remove(item.id);
                }
            });
            if (++scheduled == 32)
            {
                break;
            }
        }
    }
}

package com.bowlsofmayo;

import java.io.IOException;
import java.util.concurrent.TimeUnit;
import okhttp3.HttpUrl;
import okhttp3.MediaType;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.RequestBody;
import okhttp3.Response;
import okio.BufferedSource;

final class BridgeClient
{
    static final class HttpException extends IOException
    {
        private final int statusCode;

        HttpException(int statusCode, String message)
        {
            super(message);
            this.statusCode = statusCode;
        }

        boolean rejectsEvent()
        {
            return statusCode == 400 || statusCode == 403 || statusCode == 413 || statusCode == 422;
        }
    }

    private static final MediaType JSON = MediaType.parse("application/json; charset=utf-8");
    private final OkHttpClient http;
    private final String base;
    private final String token;

    BridgeClient(OkHttpClient http, String base, String token)
    {
        HttpUrl url = HttpUrl.parse(base);
        if (url == null || !url.username().isEmpty() || !url.password().isEmpty() ||
            url.query() != null || url.fragment() != null)
        {
            throw new IllegalArgumentException("Invalid bridge URL");
        }
        boolean local = url.host().equals("localhost") || url.host().equals("127.0.0.1") ||
            url.host().equals("::1");
        if (!url.isHttps() && !local)
        {
            throw new IllegalArgumentException("Remote bridges require HTTPS");
        }
        if (token == null || token.trim().length() < 32)
        {
            throw new IllegalArgumentException("Configure your member token (32+ characters)");
        }
        this.http = http.newBuilder().followRedirects(false).followSslRedirects(false)
            .connectTimeout(5, TimeUnit.SECONDS).readTimeout(10, TimeUnit.SECONDS)
            .callTimeout(15, TimeUnit.SECONDS).build();
        this.base = base.replaceAll("/+$", "");
        this.token = token.trim();
    }

    String get(String path) throws IOException
    {
        return execute(new Request.Builder().url(base + path).get());
    }

    byte[] getBytes(String path, int limit) throws IOException
    {
        try (Response response = http.newCall(new Request.Builder().url(base + path).get()
            .header("Authorization", "Bearer " + token).build()).execute())
        {
            if (!response.isSuccessful() || response.body() == null)
            {
                throw new IOException("Bridge HTTP " + response.code());
            }
            BufferedSource source = response.body().source();
            if (source.request(limit + 1L))
            {
                throw new IOException("Bridge response too large");
            }
            return source.getBuffer().readByteArray();
        }
    }

    void post(String path, String json) throws IOException
    {
        execute(new Request.Builder().url(base + path).post(RequestBody.create(JSON, json)));
    }

    private String execute(Request.Builder request) throws IOException
    {
        try (Response response = http.newCall(request.header("Authorization", "Bearer " + token).build()).execute())
        {
            if (!response.isSuccessful())
            {
                String reason = null;
                if (response.body() != null)
                {
                    try
                    {
                        BufferedSource source = response.body().source();
                        source.request(4096);
                        String text = source.getBuffer().clone().readUtf8(Math.min(4096, source.getBuffer().size()));
                        com.google.gson.JsonObject error = new com.google.gson.JsonParser().parse(text).getAsJsonObject();
                        if (error.has("error"))
                        {
                            reason = error.get("error").getAsString();
                        }
                    }
                    catch (RuntimeException | IOException ignored)
                    {
                        // fall back to the generic message
                    }
                }
                throw new HttpException(response.code(), "Bridge HTTP " + response.code() + ": " +
                    (reason != null ? reason : "check URL, token and assigned RS name"));
            }
            if (response.body() == null)
            {
                throw new IOException("Empty bridge response");
            }
            return response.body().string();
        }
    }
}

package com.bowlsofmayo;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.GridLayout;
