@PluginDescriptor(
    name = "Group Iron Companion",
    description = "Private GIM banks, world map and Discord updates",
    tags = {"group", "ironman", "discord", "bank"}
)
public class ClanTrackerPlugin extends Plugin
{
    private static final Logger LOG = LoggerFactory.getLogger(ClanTrackerPlugin.class);
    private static final long LOGO_REFRESH_MILLIS = TimeUnit.MINUTES.toMillis(5);
    private static final BufferedImage COMPANION_ICON = ImageUtil.loadImageResource(ClanTrackerPlugin.class, "companion-icon.png");

    @Inject private Client client;
    @Inject private ClientThread clientThread;
    @Inject private ClanTrackerConfig config;
    @Inject private Gson runeLiteGson;
    @Inject private ClientToolbar toolbar;
    @Inject private ItemManager itemManager;
    @Inject private WorldMapPointManager mapManager;
    @Inject private okhttp3.OkHttpClient http;

    private final ConcurrentLinkedQueue<TrackerData.Event> events = new ConcurrentLinkedQueue<>();
    private final Map<Quest, QuestState> quests = new HashMap<>();
    private final Map<String, FeatureParser.Kill> kills = new HashMap<>();
    private final List<PendingLoot> loot = new ArrayList<>();
    private volatile TrackerData.Member snapshot;
    private volatile boolean running;
    private Gson gson;
    private volatile int generation;
    private volatile int accessRevision;
    private final Object uploadStateLock = new Object();
    private volatile boolean accessResetPending;
    private ScheduledExecutorService worker;
    private ScheduledExecutorService xpWorker;
    private final LiveXpTracker liveXp = new LiveXpTracker();
    private volatile long nextXpAttempt;
    private ClanPanel panel;
    private final SyncStatus syncStatus = new SyncStatus();
    private volatile NavigationButton button;
    private volatile BufferedImage logo;
    private volatile long logoFetchedAt;
    private volatile BufferedImage mapIcon;
    private volatile long mapIconFetchedAt;
    private static final long MAP_ICON_REFRESH_MILLIS = TimeUnit.SECONDS.toMillis(30);
    private String account;
    private List<TrackerData.BankItem> bank;
    private long bankUpdatedAt;
    private List<TrackerData.BankItem> groupStorage;
    private long groupStorageUpdatedAt;
    private int ticks;
    private boolean questsReady;
    private boolean questsDirty = true;
    private List<TrackerData.Member> groupMembers = Collections.emptyList();
    private final BankSnapshots bankSnapshots = new BankSnapshots();

    @Provides
    ClanTrackerConfig provideConfig(ConfigManager manager)
    {
        return manager.getConfig(ClanTrackerConfig.class);
    }

    @Override
    protected void startUp()
    {
        gson = runeLiteGson.newBuilder().serializeNulls().create();
        panel = new ClanPanel(itemManager);
        panel.setConnectionEnabled(config.enableConnection());
        running = true;
        logoFetchedAt = 0;
        mapIconFetchedAt = 0;
        int currentGeneration = ++generation;
        SwingUtilities.invokeLater(() -> {
            if (active(currentGeneration))
            {
                syncStatus.clear();
            }
        });
        setSidebarIcon(COMPANION_ICON);
        refreshSidebarIcon();
        worker = Executors.newSingleThreadScheduledExecutor(task -> {
            Thread thread = new Thread(task, "bowlsofmayo-bridge");
            thread.setDaemon(true);
            return thread;
        });
        worker.scheduleWithFixedDelay(() -> synchronize(currentGeneration), 0, 5, TimeUnit.SECONDS);
        xpWorker = Executors.newSingleThreadScheduledExecutor(task -> {
            Thread thread = new Thread(task, "bowlsofmayo-live-xp");
            thread.setDaemon(true);
            return thread;
        });
        nextXpAttempt = 0;
        xpWorker.scheduleWithFixedDelay(() -> sendLiveXp(currentGeneration), 0, 250, TimeUnit.MILLISECONDS);
    }

    @Override
    protected void shutDown()
    {
        synchronized (uploadStateLock)
        {
            running = false;
            generation++;
            int discarded = events.size() + loot.size();
            events.clear();
            snapshot = null;
            accessResetPending = false;
            if (discarded > 0)
            {
                LOG.warn("Group Iron Companion stopped; discarded {} unsent alerts", discarded);
            }
        }
        if (worker != null)
        {
            worker.shutdownNow();
        }
        if (xpWorker != null)
        {
            xpWorker.shutdownNow();
        }
        mapManager.removeIf(GroupMapPoint.class::isInstance);
        NavigationButton current = button;
        SwingUtilities.invokeLater(() -> {
            if (current != null)
            {
                toolbar.removeNavigation(current);
            }
        });
        button = null;
        logo = null;
        mapIcon = null;
        groupMembers = Collections.emptyList();
        resetAccount();
    }

    private void resetAccount()
    {
        liveXp.clear();
        account = null;
        bank = null;
        bankUpdatedAt = 0;
        groupStorage = null;
        groupStorageUpdatedAt = 0;
        ticks = 0;
        questsReady = false;
        questsDirty = true;
        quests.clear();
        kills.clear();
        loot.clear();
    }

    @Subscribe
    public void onGameStateChanged(GameStateChanged event)
    {
        if (event.getGameState() != GameState.LOGGED_IN)
        {
            liveXp.clearBaseline();
        }
        if (event.getGameState() == GameState.LOGIN_SCREEN)
        {
            flushLoot(true);
            resetAccount();
            snapshot = null;
            mapManager.removeIf(GroupMapPoint.class::isInstance);
        }
        else if (event.getGameState() != GameState.LOGGED_IN)
        {
            snapshot = null;
        }
    }

    @Subscribe
    public void onGameTick(GameTick event)
    {
        if (!config.enableConnection())
        {
            return;
        }
        if (client.getGameState() != GameState.LOGGED_IN || client.getLocalPlayer() == null)
        {
            return;
        }
        String name = Text.removeTags(client.getLocalPlayer().getName()).replace('\u00a0', ' ');
        if (!name.equals(account))
        {
            resetAccount();
            account = name;
        }
        ticks++;
        for (Skill skill : Skill.values())
        {
            if (skill != Skill.OVERALL)
            {
                liveXp.baseline(skill, client.getSkillExperience(skill));
            }
        }
        if (questsDirty)
        {
            checkQuests();
            questsDirty = false;
        }
        flushLoot(false);
        if (ticks == 1 || ticks % 10 == 0)
        {
            captureSnapshot();
            if (config.shareBank())
            {
                bankSnapshots.prepareIcons(itemManager, bank, groupStorage);
            }
            updateMap(groupMembers);
        }
    }

    private void captureSnapshot()
    {
        if (accessResetPending)
        {
            return;
        }
        int expectedAccessRevision = accessRevision;
        TrackerData.Member member = new TrackerData.Member();
        member.username = account;
        member.observedAt = System.currentTimeMillis();
        member.bankShared = config.shareBank();
        member.questPoints = client.getVarpValue(VarPlayerID.QP);
        for (Skill skill : Skill.values())
        {
            if (skill == Skill.OVERALL)
            {
                continue;
            }
            TrackerData.Stat stat = new TrackerData.Stat();
            stat.level = client.getRealSkillLevel(skill);
            stat.xp = client.getSkillExperience(skill);
            member.stats.put(skill.name(), stat);
        }
        if (config.shareLocation())
        {
            WorldPoint point = WorldPoint.fromLocalInstance(client, client.getLocalPlayer().getLocalLocation());
            member.position = new TrackerData.Position();
            member.position.x = point.getX();
            member.position.y = point.getY();
            member.position.plane = point.getPlane();
            member.position.world = client.getWorld();
        }
        if (config.shareBank() && bank != null)
        {
            member.bank = bank;
            member.bankUpdatedAt = bankUpdatedAt;
        }
        if (config.shareBank() && groupStorage != null)
        {
            member.groupStorage = groupStorage;
            member.groupStorageUpdatedAt = groupStorageUpdatedAt;
        }
        synchronized (uploadStateLock)
        {
            if (!accessResetPending && config.enableConnection() && accessRevision == expectedAccessRevision)
            {
                snapshot = member;
            }
        }
    }

    @Subscribe
    public void onStatChanged(StatChanged event)
    {
        if (accessResetPending || !config.enableConnection() || account == null || client.getGameState() != GameState.LOGGED_IN ||
            event.getSkill() == null || event.getSkill() == Skill.OVERALL)
        {
            return;
        }
        liveXp.observe(account, event, client.getRealSkillLevel(event.getSkill()),
            config.shareLiveXp(), System.currentTimeMillis());
    }

    private void sendLiveXp(int expectedGeneration)
    {
        int expectedAccessRevision = accessRevision;
        if (!active(expectedGeneration) || !config.enableConnection() || !config.shareLiveXp() || !liveXp.hasPending() ||
            System.currentTimeMillis() < nextXpAttempt)
        {
            return;
        }
        try
        {
            if (canSync(expectedGeneration, expectedAccessRevision) && config.shareLiveXp())
            {
                LiveXpTracker.Batch batch = liveXp.batch(System.currentTimeMillis());
                if (batch.expired > 0)
                {
                    showStatus(SyncStatus.Channel.XP_EXPIRY, "Live XP: " + batch.expired +
                        " unsent drops expired; they were not delivered live.", expectedGeneration, expectedAccessRevision);
                }
                if (!batch.drops.isEmpty() && canSync(expectedGeneration, expectedAccessRevision) && config.shareLiveXp())
                {
                    BridgeClient bridge = new BridgeClient(http, config.serverUrl(), config.memberToken());
                    if (canSync(expectedGeneration, expectedAccessRevision) && config.shareLiveXp())
                    {
                        liveXp.send(bridge, gson, batch);
                    }
                }
                if (!liveXp.hasPending())
                {
                    showStatus(SyncStatus.Channel.XP, "", expectedGeneration, expectedAccessRevision);
                }
            }
        }
        catch (IOException | IllegalArgumentException error)
        {
            nextXpAttempt = System.currentTimeMillis() + 5000;
            LOG.warn("BowlsofMayo live XP sync failed: {}", error.getMessage());
            showStatus(SyncStatus.Channel.XP, "Live XP not synced: " + error.getMessage(), expectedGeneration, expectedAccessRevision);
        }
    }

    @Subscribe
    public void onItemContainerChanged(ItemContainerChanged event)
    {
        if (!config.shareBank() || account == null || client.getGameState() != GameState.LOGGED_IN ||
            (event.getContainerId() != InventoryID.BANK.getId() &&
                event.getContainerId() != InventoryID.GROUP_STORAGE.getId()))
        {
            return;
        }
        if (event.getContainerId() == InventoryID.GROUP_STORAGE.getId())
        {
            groupStorage = bankSnapshots.readItems(itemManager, event.getItemContainer());
            groupStorageUpdatedAt = System.currentTimeMillis();
        }
        else
        {
            bank = bankSnapshots.readItems(itemManager, event.getItemContainer());
            bankUpdatedAt = System.currentTimeMillis();
        }
        captureSnapshot();
    }

    private void checkQuests()
    {
        // Login establishes a baseline; old completions must not generate new alerts.
        for (Quest quest : Quest.values())
        {
            QuestState state = quest.getState(client);
            QuestState previous = quests.put(quest, state);
            if (questsReady && config.questAlerts() && previous != null &&
                previous != QuestState.FINISHED && state == QuestState.FINISHED)
            {
                TrackerData.Event event = event("quest");
                event.quest = quest.getName();
                enqueue(event);
            }
        }
        questsReady = true;
    }

    @Subscribe
    public void onVarbitChanged(VarbitChanged event)
    {
        questsDirty = true;
    }

    @Subscribe
    public void onChatMessage(ChatMessage message)
    {
        if (account == null)
        {
            return;
        }
        String text = Text.removeTags(message.getMessage());
        if (message.getType() == ChatMessageType.CLAN_GIM_CHAT && config.shareChat() &&
            FeatureParser.samePlayer(Text.removeTags(message.getName()), account))
        {
            // Relay only the sender's own messages to avoid duplicates across group clients.
            TrackerData.Event event = event("chat");
            event.message = text;
            enqueue(event);
        }
        if (message.getType() != ChatMessageType.GAMEMESSAGE)
        {
            return;
        }
        FeatureParser.Kill kill = FeatureParser.parseKill(text);
        if (kill == null)
        {
            return;
        }
        FeatureParser.Kill previous = kills.put(FeatureParser.sourceKey(kill.boss), kill);
        if (config.bossAlerts() && (previous == null || previous.kc != kill.kc))
        {
            TrackerData.Event event = event("boss");
            event.id = "boss:" + FeatureParser.sourceKey(kill.boss) + ":" + kill.kc;
            event.boss = kill.boss;
            event.kc = kill.kc;
            enqueue(event);
        }
    }

    @Subscribe
    public void onLootReceived(LootReceived received)
    {
        if (account == null || !config.dropAlerts() || received.getType().name().equals("PLAYER"))
        {
            return;
        }
        TrackerData.Event event = event("loot");
        event.source = received.getName();
        event.items = new ArrayList<>();
        for (ItemStack item : received.getItems())
        {
            if (item.getId() <= 0 || item.getQuantity() <= 0)
            {
                continue;
            }
            int price = (int) Math.min(Integer.MAX_VALUE, Math.max(0, itemManager.getItemPrice(item.getId())));
            if ((long) price * item.getQuantity() < config.minimumDropValue())
            {
                continue;
            }
            TrackerData.BankItem entry = new TrackerData.BankItem();
            entry.id = item.getId();
            entry.qty = item.getQuantity();
            entry.name = itemManager.getItemComposition(item.getId()).getName();
            entry.price = (long) price;
            event.items.add(entry);
        }
        if (!event.items.isEmpty())
        {
            loot.add(new PendingLoot(event, ticks + 3));
        }
    }

    private void flushLoot(boolean force)
    {
        loot.removeIf(pending -> {
            if (!force && pending.tick > ticks)
            {
                return false;
            }
            FeatureParser.Kill kill = kills.get(FeatureParser.sourceKey(pending.event.source));
            if (kill != null && System.currentTimeMillis() - kill.observedAt < 15000)
            {
                pending.event.kc = kill.kc;
            }
            enqueue(pending.event);
            return true;
        });
    }

    private TrackerData.Event event(String type)
    {
        TrackerData.Event event = new TrackerData.Event();
        event.id = UUID.randomUUID().toString();
        event.username = account;
        event.type = type;
        return event;
    }

    private void enqueue(TrackerData.Event event)
    {
        synchronized (uploadStateLock)
        {
            if (!running || accessResetPending || !config.enableConnection() || !UploadCoordinator.eventEnabled(config, event))
            {
                return;
            }
            if (events.size() >= 2000)
            {
                LOG.error("BowlsofMayo alert queue full; cannot queue {} alert", event.type);
                showStatus("Alert queue full! Check bridge connection.");
                return;
            }
            events.add(event);
        }
    }

    private boolean active(int expectedGeneration)
    {
        return running && generation == expectedGeneration;
    }

    private boolean canSync(int expectedGeneration, int expectedAccessRevision)
    {
        return active(expectedGeneration) && !accessResetPending && config.enableConnection() &&
            accessRevision == expectedAccessRevision;
    }

    private void synchronize(int expectedGeneration)
    {
        int expectedAccessRevision = accessRevision;
        if (!config.enableConnection())
        {
            clearGroupData("Connection disabled - no data sent.", expectedGeneration, expectedAccessRevision);
            return;
        }
        if (!active(expectedGeneration))
        {
            return;
        }
        try
        {
            BridgeClient bridge = new BridgeClient(http, config.serverUrl(), config.memberToken());
            TrackerData.Member current = snapshot;
            if (current != null && canSync(expectedGeneration, expectedAccessRevision))
            {
                String json = gson.toJson(UploadCoordinator.snapshotForUpload(config, current));
                if (!canSync(expectedGeneration, expectedAccessRevision))
                {
                    return;
                }
                bridge.post("/v1/snapshot", json);
            }
            String alertStatus = UploadCoordinator.sendAlerts(bridge, gson, events, config,
                () -> canSync(expectedGeneration, expectedAccessRevision));
            if (!canSync(expectedGeneration, expectedAccessRevision))
            {
                return;
            }
            showStatus(SyncStatus.Channel.ALERTS, alertStatus, expectedGeneration, expectedAccessRevision);
            TrackerData.Group group = gson.fromJson(bridge.get("/v1/group"), TrackerData.Group.class);
            if (group == null || group.members == null)
            {
                throw new IOException("Bridge returned an invalid group response");
            }
            SwingUtilities.invokeLater(() -> {
                if (active(expectedGeneration) && accessRevision == expectedAccessRevision)
                {
                    panel.update(group);
                }
            });
            clientThread.invokeLater(() -> {
                if (active(expectedGeneration) && accessRevision == expectedAccessRevision)
                {
                    groupMembers = group.members;
                    updateMap(group.members);
                }
            });
            if (active(expectedGeneration))
            {
                showStatus(SyncStatus.Channel.GROUP, "", expectedGeneration, expectedAccessRevision);
            }
            uploadBankIcons(bridge, current, group, expectedGeneration, expectedAccessRevision);
            refreshRemoteImages(bridge, expectedGeneration, expectedAccessRevision);
        }
        catch (IOException | IllegalArgumentException | com.google.gson.JsonParseException error)
        {
            LOG.warn("BowlsofMayo bridge sync failed: {}", error.getMessage());
            clearGroupData("Not synced: " + error.getMessage(), expectedGeneration, expectedAccessRevision);
        }
    }

    private void uploadBankIcons(BridgeClient bridge, TrackerData.Member current, TrackerData.Group group,
        int expectedGeneration, int expectedAccessRevision)
    {
        if (!canSync(expectedGeneration, expectedAccessRevision))
        {
            return;
        }
        try
        {
            if (current != null && current.bankShared && config.shareBank())
            {
                TrackerData.Icons upload = new TrackerData.Icons();
                upload.username = current.username;
                for (TrackerData.BankItem item : BankSnapshots.combinedItems(current.bank, current.groupStorage))
                {
                    String image = bankSnapshots.icon(item.id);
                    if (image != null && (group.icons == null || !group.icons.containsKey(item.id)))
                    {
                        upload.icons.put(item.id, image);
                        if (upload.icons.size() == 32)
                        {
                            break;
                        }
                    }
                }
                if (!upload.icons.isEmpty() && config.shareBank() && canSync(expectedGeneration, expectedAccessRevision))
                {
                    bridge.post("/v1/icons", gson.toJson(upload));
                }
            }
            showStatus(SyncStatus.Channel.BANK_ICONS, "", expectedGeneration, expectedAccessRevision);
        }
        catch (IOException error)
        {
            LOG.warn("Bank icons not synced: {}", error.getMessage());
            showStatus(SyncStatus.Channel.BANK_ICONS, "Bank icons not synced; will retry: " +
                error.getMessage(), expectedGeneration, expectedAccessRevision);
        }
    }

    private void clearGroupData(String message, int expectedGeneration, int expectedAccessRevision)
    {
        SwingUtilities.invokeLater(() -> {
            if (active(expectedGeneration) && accessRevision == expectedAccessRevision)
            {
                syncStatus.set(SyncStatus.Channel.GROUP, message);
                panel.clear(syncStatus.text());
                panel.setConnectionEnabled(config.enableConnection());
            }
        });
        clientThread.invokeLater(() -> {
            if (active(expectedGeneration) && accessRevision == expectedAccessRevision)
            {
                groupMembers = Collections.emptyList();
                mapManager.removeIf(GroupMapPoint.class::isInstance);
            }
        });
    }

    private void updateMap(List<TrackerData.Member> members)
    {
        mapManager.removeIf(GroupMapPoint.class::isInstance);
        if (!config.showMap() || client.getGameState() != GameState.LOGGED_IN)
        {
            return;
        }
        for (TrackerData.Member member : members)
        {
            TrackerData.Position position = member.position;
            if (position == null || System.currentTimeMillis() - member.updatedAt > 30000 ||
                FeatureParser.samePlayer(member.username, account))
            {
                continue;
            }
            GroupMapPoint point = new GroupMapPoint(
                new WorldPoint(position.x, position.y, position.plane), mapMarker());
            point.setName(member.username);
            point.setTooltip(member.username + " - World " + position.world +
                (position.world == client.getWorld() ? "" : " (different world)"));
            point.setSnapToEdge(true);
            point.setJumpOnClick(true);
            mapManager.add(point);
        }

        Player localPlayer = client.getLocalPlayer();
        if (localPlayer != null)
        {
            WorldPoint position = WorldPoint.fromLocalInstance(client, localPlayer.getLocalLocation());
            GroupMapPoint point = new GroupMapPoint(position, mapMarker());
            point.setName("You");
            point.setTooltip((account == null ? localPlayer.getName() : account) +
                " - World " + client.getWorld());
            point.setSnapToEdge(true);
            point.setJumpOnClick(true);
            mapManager.add(point);
        }
    }

    private void showStatus(String status)
    {
        showStatus(SyncStatus.Channel.ALERTS, status, generation, accessRevision);
    }

    private void showStatus(SyncStatus.Channel channel, String status, int expectedGeneration, int expectedAccessRevision)
    {
        SwingUtilities.invokeLater(() -> {
            if (active(expectedGeneration) && accessRevision == expectedAccessRevision)
            {
                syncStatus.set(channel, status);
                panel.setStatus(syncStatus.text());
            }
        });
    }

    @Subscribe
    public void onConfigChanged(ConfigChanged event)
    {
        if (!"bowlsofmayo".equals(event.getGroup()))
        {
            return;
        }
        switch (event.getKey())
        {
            case "enableConnection":
                resetUploadAccess();
                clearGroupData(config.enableConnection() ? "Waiting for sync." :
                    "Connection disabled - no data sent.", generation, accessRevision);
                break;
            case "shareLiveXp":
            case "shareBank":
            case "shareLocation":
            case "shareChat":
            case "bossAlerts":
            case "dropAlerts":
            case "questAlerts":
                synchronized (uploadStateLock)
                {
                    accessRevision++;
                    snapshot = null;
                    events.removeIf(queued -> !UploadCoordinator.eventEnabled(config, queued));
                }
                if (event.getKey().equals("shareLiveXp"))
                {
                    liveXp.discardPending();
                    clientThread.invokeLater(liveXp::clear);
                    showStatus(SyncStatus.Channel.XP, "", generation, accessRevision);
                    showStatus(SyncStatus.Channel.XP_EXPIRY, "", generation, accessRevision);
                }
                if (event.getKey().equals("shareBank"))
                {
                    clientThread.invokeLater(() -> {
                        bank = null;
                        bankUpdatedAt = 0;
                        groupStorage = null;
                        groupStorageUpdatedAt = 0;
                    });
                }
                if (event.getKey().equals("dropAlerts"))
                {
                    clientThread.invokeLater(loot::clear);
                }
                break;
            case "serverUrl":
            case "memberToken":
                resetUploadAccess();
                clearGroupData("Access changed - waiting for sync.", generation, accessRevision);
                logo = null;
                mapIcon = null;
                mapIconFetchedAt = 0;
                logoFetchedAt = 0;
                refreshSidebarIcon();
                break;
            case "sidebarIcon":
            case "sidebarItemId":
                logoFetchedAt = 0;
                showStatus(SyncStatus.Channel.LOGO_IMAGE, "", generation, accessRevision);
                refreshSidebarIcon();
                break;
            default:
                break;
        }
    }

    private void resetUploadAccess()
    {
        synchronized (uploadStateLock)
        {
            accessResetPending = true;
            accessRevision++;
            snapshot = null;
            events.clear();
            liveXp.discardPending();
        }
        nextXpAttempt = 0;
        int expectedGeneration = generation;
        int expectedAccessRevision = accessRevision;
        SwingUtilities.invokeLater(() -> {
            if (active(expectedGeneration) && accessRevision == expectedAccessRevision)
            {
                syncStatus.clear();
                panel.setStatus("");
            }
        });
        clientThread.invokeLater(() -> {
            synchronized (uploadStateLock)
            {
                if (!active(expectedGeneration))
                {
                    return;
                }
                resetAccount();
                accessResetPending = false;
            }
        });
    }

    private void refreshSidebarIcon()
    {
        if (!running)
        {
            return;
        }
        SidebarIcon choice = config.sidebarIcon();
        if (choice == SidebarIcon.COMPANION_SHIELD)
        {
            setSidebarIcon(COMPANION_ICON);
            return;
        }
        if (choice == SidebarIcon.GROUP_LOGO)
        {
            BufferedImage current = logo;
            setSidebarIcon(current != null ? current : COMPANION_ICON);
            return;
        }
        if (choice == SidebarIcon.DOT)
        {
            setSidebarIcon(TrackerImages.marker());
            return;
        }
        int itemId = choice == SidebarIcon.CUSTOM_ITEM ? config.sidebarItemId() : choice.itemId();
        AsyncBufferedImage image = itemManager.getImage(itemId, choice.quantity(), choice.quantity() > 1);
        image.onLoaded(() -> {
            if (running && config.sidebarIcon() == choice)
            {
                setSidebarIcon(TrackerImages.iconImage(image));
            }
        });
    }

    private void refreshRemoteImages(BridgeClient bridge, int expectedGeneration, int expectedAccessRevision)
    {
        if (!canSync(expectedGeneration, expectedAccessRevision))
        {
            return;
        }
        if (System.currentTimeMillis() - mapIconFetchedAt > MAP_ICON_REFRESH_MILLIS)
        {
            mapIconFetchedAt = System.currentTimeMillis();
            try
            {
                fetchMapIcon(bridge, expectedGeneration, expectedAccessRevision);
                showStatus(SyncStatus.Channel.MAP_IMAGE, "", expectedGeneration, expectedAccessRevision);
            }
            catch (IOException error)
            {
                LOG.warn("Map icon unavailable: {}", error.getMessage());
                showStatus(SyncStatus.Channel.MAP_IMAGE, "Map icon unavailable; using cached/default icon: " +
                    error.getMessage(), expectedGeneration, expectedAccessRevision);
            }
        }
        if (canSync(expectedGeneration, expectedAccessRevision) && config.sidebarIcon() == SidebarIcon.GROUP_LOGO &&
            System.currentTimeMillis() - logoFetchedAt > LOGO_REFRESH_MILLIS)
        {
            logoFetchedAt = System.currentTimeMillis();
            fetchLogo(bridge, expectedGeneration, expectedAccessRevision);
        }
    }

    private void fetchLogo(BridgeClient bridge, int expectedGeneration, int expectedAccessRevision)
    {
        try
        {
            BufferedImage image = TrackerImages.readLogo(bridge);
            synchronized (uploadStateLock)
            {
                if (canSync(expectedGeneration, expectedAccessRevision))
                {
                    logo = image;
                    if (config.sidebarIcon() == SidebarIcon.GROUP_LOGO)
                    {
                        setSidebarIcon(logo);
                    }
                    showStatus(SyncStatus.Channel.LOGO_IMAGE, "", expectedGeneration, expectedAccessRevision);
                }
            }
        }
        catch (IOException error)
        {
            LOG.warn("Group logo unavailable: {}", error.getMessage());
            showStatus(SyncStatus.Channel.LOGO_IMAGE, "Group logo unavailable; using cached/default icon: " +
                error.getMessage(), expectedGeneration, expectedAccessRevision);
        }
    }

    private BufferedImage mapMarker()
    {
        BufferedImage current = mapIcon;
        return current != null ? current : TrackerImages.marker();
    }

    private void fetchMapIcon(BridgeClient bridge, int expectedGeneration, int expectedAccessRevision) throws IOException
    {
        BufferedImage image = TrackerImages.readMapIcon(bridge);
        clientThread.invokeLater(() -> {
            if (canSync(expectedGeneration, expectedAccessRevision))
            {
                mapIcon = image;
                updateMap(groupMembers);
            }
        });
    }

    private void setSidebarIcon(BufferedImage icon)
    {
        int expectedGeneration = generation;
        int expectedAccessRevision = accessRevision;
        SwingUtilities.invokeLater(() -> {
            if (!active(expectedGeneration) || accessRevision != expectedAccessRevision || panel == null)
            {
                return;
            }
            NavigationButton previous = button;
            button = NavigationButton.builder().tooltip("Group Iron Companion")
                .icon(icon).priority(7).panel(panel).build();
            if (previous != null)
            {
                toolbar.removeNavigation(previous);
            }
            toolbar.addNavigation(button);
        });
    }

    private static final class GroupMapPoint extends WorldMapPoint
    {
        private GroupMapPoint(WorldPoint point, BufferedImage image)
        {
            super(point, image);
        }
    }

    private static final class PendingLoot
    {
        private final TrackerData.Event event;
        private final int tick;

        private PendingLoot(TrackerData.Event event, int tick)
        {
            this.event = event;
            this.tick = tick;
        }
    }
}

package com.bowlsofmayo;

import java.util.Locale;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

final class FeatureParser
{
    private static final Pattern KILL = Pattern.compile(
        "^Your (.+?) (?:kill|harvest|completion|subdued) count is:\\s*([0-9,]+)\\b",
        Pattern.CASE_INSENSITIVE);
    private static final Pattern COMPLETION = Pattern.compile(
        "^Your (?:completion count for|completed|subdued) (.+?) (?:count )?is:\\s*([0-9,]+)\\b",
        Pattern.CASE_INSENSITIVE);

    static Kill parseKill(String message)
    {
        Matcher matcher = KILL.matcher(message);
        if (!matcher.find())
        {
            matcher = COMPLETION.matcher(message);
            if (!matcher.find())
            {
                return null;
            }
        }
        String digits = matcher.group(2).replace(",", "");
        if (digits.length() > 10)
        {
            return null;
        }
        long count = Long.parseLong(digits);
        if (count < 1 || count > Integer.MAX_VALUE)
        {
            return null;
        }
        return new Kill(matcher.group(1), (int) count);
    }

    static boolean samePlayer(String left, String right)
    {
        return left != null && right != null && normalize(left).equals(normalize(right));
    }

    private static String normalize(String value)
    {
        return value.replace('\u00a0', ' ').replace('_', ' ').trim().toLowerCase(Locale.ROOT);
    }

    static String sourceKey(String value)
    {
        String key = normalize(value).replaceAll("[^a-z0-9]", "");
        switch (key)
        {
            case "thegauntlet": return "gauntlet";
            case "thecorruptedgauntlet": return "corruptedgauntlet";
            case "theleviathan": return "leviathan";
            case "thewhisperer": return "whisperer";
            default: return key;
        }
    }

    static final class Kill
    {
        final String boss;
        final int kc;
        final long observedAt = System.currentTimeMillis();

        Kill(String boss, int kc)
        {
            this.boss = boss;
            this.kc = kc;
        }
    }
}

package com.bowlsofmayo;

import java.io.IOException;
import java.util.ArrayList;
import java.util.EnumMap;
import java.util.List;
import java.util.Map;
import java.util.UUID;
import java.util.concurrent.ConcurrentLinkedQueue;
import net.runelite.api.Skill;
import net.runelite.api.events.StatChanged;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

final class LiveXpTracker
{
    private static final Logger LOG = LoggerFactory.getLogger(LiveXpTracker.class);
    private final Map<Skill, Integer> experience = new EnumMap<>(Skill.class);
    private final ConcurrentLinkedQueue<Drop> pending = new ConcurrentLinkedQueue<>();

    static final class Drop
    {
        String id;
        String skill;
        String username;
        int amount;
        int totalXp;
        int level;
        long observedAt;
    }

    static final class Batch
    {
        String username;
        List<Drop> drops = new ArrayList<>();
        transient int expired;
    }

    void baseline(Skill skill, int xp)
    {
        experience.putIfAbsent(skill, xp);
    }

    void clearBaseline()
    {
        experience.clear();
    }

    boolean hasPending()
    {
        return !pending.isEmpty();
    }

    void clear()
    {
        clearBaseline();
        discardPending();
    }

    void discardPending()
    {
        pending.clear();
    }

    void observe(String username, StatChanged event, int level, boolean enabled, long now)
    {
        Skill skill = event.getSkill();
        if (skill == Skill.OVERALL || skill == null)
        {
            return;
        }
        Integer previous = experience.put(skill, event.getXp());
        if (!enabled || previous == null || event.getXp() <= previous)
        {
            return;
        }
        if (pending.size() >= 2000)
        {
            LOG.error("Live XP queue full; XP drop was not queued");
            return;
        }
        Drop drop = new Drop();
        drop.id = UUID.randomUUID().toString();
        drop.username = username;
        drop.skill = skill.name();
        drop.amount = event.getXp() - previous;
        drop.totalXp = event.getXp();
        drop.level = level;
        drop.observedAt = now;
        pending.add(drop);
    }

    Batch batch(long now)
    {
        int expired = 0;
        for (Drop drop : pending)
        {
            if (now - drop.observedAt > 25000 && pending.remove(drop))
            {
                expired++;
            }
        }
        if (expired > 0)
        {
            LOG.warn("Expired {} unsent live XP drops; historical XP still syncs via snapshots", expired);
        }
        Batch batch = new Batch();
        batch.expired = expired;
        for (Drop drop : pending)
        {
            if (batch.username == null)
            {
                batch.username = drop.username;
            }
            if (batch.username.equals(drop.username))
            {
                batch.drops.add(drop);
            }
            if (batch.drops.size() == 50)
            {
                break;
            }
        }
        return batch;
    }

    void send(BridgeClient bridge, com.google.gson.Gson gson, Batch batch) throws IOException
    {
        if (!batch.drops.isEmpty())
        {
            bridge.post("/v1/xp-drops", gson.toJson(batch));
            batch.drops.forEach(pending::remove);
        }
    }
}

